using CompanyManagement.Api.Data; using CompanyManagement.Api.Models; using Microsoft.EntityFrameworkCore;
namespace CompanyManagement.Api.Repositories;
public interface IClienteRepository { Task<List<Cliente>> All(); Task<Cliente?> Get(int id); Task<bool> EmailExists(string email,int? exceptId=null); Task Add(Cliente c); void Remove(Cliente c); Task<bool> HasOrders(int id); Task Save(); }
public class ClienteRepository(AppDbContext db):IClienteRepository { public Task<List<Cliente>> All()=>db.Clientes.AsNoTracking().OrderBy(x=>x.Nombre).ToListAsync(); public Task<Cliente?> Get(int id)=>db.Clientes.FindAsync(id).AsTask(); public Task<bool> EmailExists(string e,int? id=null)=>db.Clientes.AnyAsync(x=>x.Email==e && (!id.HasValue||x.Id!=id)); public Task Add(Cliente c)=>db.Clientes.AddAsync(c).AsTask(); public void Remove(Cliente c)=>db.Clientes.Remove(c); public Task<bool> HasOrders(int id)=>db.Ordenes.AnyAsync(x=>x.ClienteId==id); public Task Save()=>db.SaveChangesAsync(); }
public interface IOrdenRepository { Task<List<Orden>> All(); Task<Orden?> Get(int id); Task<List<Orden>> ForClient(int clientId); Task Add(Orden o); Task Save(); }
public class OrdenRepository(AppDbContext db):IOrdenRepository { public Task<List<Orden>> All()=>db.Ordenes.AsNoTracking().OrderByDescending(x=>x.FechaOrden).ToListAsync(); public Task<Orden?> Get(int id)=>db.Ordenes.FindAsync(id).AsTask(); public Task<List<Orden>> ForClient(int id)=>db.Ordenes.AsNoTracking().Where(x=>x.ClienteId==id).OrderByDescending(x=>x.FechaOrden).ToListAsync(); public Task Add(Orden o)=>db.Ordenes.AddAsync(o).AsTask(); public Task Save()=>db.SaveChangesAsync(); }
